import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'components';
}

<div class="container">
    <div class="sidebar">
      <app-sidebar></app-sidebar>
    </div>
    <div class="main-content">
      <router-outlet></router-outlet>
    </div>
</div>
